import{_ as e,C as r,o as p,c as i,a5 as n,E as a}from"./chunks/framework.B5tqjWbr.js";const h=JSON.parse('{"title":"COM-01 CAN总线基础","description":"","frontmatter":{"date":"2026-06-08T00:00:00.000Z","section":"电机控制","chapter":"communication","chapterTitle":"通信与协议","chapterOrder":40,"category":"通信与协议","source":"motor","visibility":"public","title":"COM-01 CAN总线基础","tags":["motor-control"],"status":"learning","summary":"> 路径：📡 工业通信协议 > COM-01","navGroup":"工程与生态","navGroupOrder":50},"headers":[],"relativePath":"content/motor/communication/COM-01-CAN-Basics.md","filePath":"content/motor/communication/COM-01-CAN-Basics.md","lastUpdated":null}'),o={name:"content/motor/communication/COM-01-CAN-Basics.md"};function l(m,s,d,E,c,A){const t=r("MermaidDiagram");return p(),i("div",null,[s[0]||(s[0]=n('<h1 id="com-01-can总线基础" tabindex="-1">COM-01 CAN总线基础 <a class="header-anchor" href="#com-01-can总线基础" aria-label="Permalink to &quot;COM-01 CAN总线基础&quot;">​</a></h1><blockquote><p>路径：📡 工业通信协议 &gt; COM-01</p></blockquote><p><strong>难度：</strong> ★★★☆☆</p><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>CAN（Controller Area Network）是由Bosch于1986年开发的串行通信协议，最初面向汽车领域，现已广泛应用于工业自动化、电机控制、医疗设备等场景。CAN协议的核心设计理念是：高可靠性、实时性和灵活性——这正是电机控制系统对通信总线的核心要求。</p><p>在电机控制系统中，CAN总线承担着多轴协调、指令下发、状态反馈、故障诊断等关键任务。理解CAN协议的底层机制，对于设计可靠的电机驱动通信系统至关重要。本文将从帧格式、仲裁机制、位填充、错误处理和物理层拓扑五个维度，深入剖析CAN 2.0A/2.0B的技术细节。</p><h2 id="正文" tabindex="-1">正文 <a class="header-anchor" href="#正文" aria-label="Permalink to &quot;正文&quot;">​</a></h2><h3 id="_1-can-2-0a-2-0b-帧格式详解" tabindex="-1">1. CAN 2.0A/2.0B 帧格式详解 <a class="header-anchor" href="#_1-can-2-0a-2-0b-帧格式详解" aria-label="Permalink to &quot;1. CAN 2.0A/2.0B 帧格式详解&quot;">​</a></h3><p>CAN 2.0定义了两种帧格式：<strong>标准帧（CAN 2.0A）</strong> 使用11位标识符，<strong>扩展帧（CAN 2.0B）</strong> 使用29位标识符。CAN总线上的报文有四种类型：数据帧、远程帧、错误帧和过载帧。</p><h4 id="_1-1-数据帧结构" tabindex="-1">1.1 数据帧结构 <a class="header-anchor" href="#_1-1-数据帧结构" aria-label="Permalink to &quot;1.1 数据帧结构&quot;">​</a></h4><p>数据帧是CAN通信中最核心的帧类型，用于承载应用数据。其完整结构如下：</p>',11)),a(t,{code:"flowchart%20LR%0A%20%20%20%20subgraph%20%E6%A0%87%E5%87%86%E5%B8%A7%5B%22%E6%A0%87%E5%87%86%E5%B8%A7%EF%BC%88CAN%202.0A%EF%BC%89%E4%BD%8D%E5%BA%8F%E5%88%97%22%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20S1%5B%22SOF%5Cn1bit%22%5D%20--%3E%20S2%5B%22%E4%BB%B2%E8%A3%81%E5%9C%BA(12bit)%5Cn11bit%20ID%20%2B%20RTR%22%5D%20--%3E%20S3%5B%22%E6%8E%A7%E5%88%B6%E5%9C%BA%5Cn6bit%22%5D%20--%3E%20S4%5B%22%E6%95%B0%E6%8D%AE%E5%9C%BA%5Cn0~8%E5%AD%97%E8%8A%82%22%5D%20--%3E%20S5%5B%22CRC%E5%9C%BA%5Cn16bit%22%5D%20--%3E%20S6%5B%22ACK%5Cn2bit%22%5D%20--%3E%20S7%5B%22EOF%5Cn7bit%22%5D%20--%3E%20S8%5B%22IFS%5Cn3bit%22%5D%0A%20%20%20%20end%0A"}),a(t,{code:"flowchart%20LR%0A%20%20%20%20subgraph%20%E6%89%A9%E5%B1%95%E5%B8%A7%5B%22%E6%89%A9%E5%B1%95%E5%B8%A7%EF%BC%88CAN%202.0B%EF%BC%89%E4%BD%8D%E5%BA%8F%E5%88%97%22%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20E1%5B%22SOF%5Cn1bit%22%5D%20--%3E%20E2%5B%22%E4%BB%B2%E8%A3%81%E5%9C%BA(32bit)%5Cn11bit%20Base%20ID%2BSRR%2BIDE%5Cn%2B18bit%20Ext%20ID%2BRTR%22%5D%20--%3E%20E3%5B%22%E6%8E%A7%E5%88%B6%E5%9C%BA%5Cn6bit%22%5D%20--%3E%20E4%5B%22%E6%95%B0%E6%8D%AE%E5%9C%BA%5Cn0~8%E5%AD%97%E8%8A%82%22%5D%20--%3E%20E5%5B%22CRC%E5%9C%BA%5Cn16bit%22%5D%20--%3E%20E6%5B%22ACK%5Cn2bit%22%5D%20--%3E%20E7%5B%22EOF%5Cn7bit%22%5D%20--%3E%20E8%5B%22IFS%5Cn3bit%22%5D%0A%20%20%20%20end%0A"}),s[1]||(s[1]=n(`<h4 id="_1-2-各字段详解" tabindex="-1">1.2 各字段详解 <a class="header-anchor" href="#_1-2-各字段详解" aria-label="Permalink to &quot;1.2 各字段详解&quot;">​</a></h4><p><strong>SOF（Start of Frame）</strong> — 1位显性位</p><p>SOF标志一帧的开始。所有节点在检测到总线空闲后，通过发送显性位来同步。SOF的下降沿同时作为所有节点的硬同步信号。</p><blockquote><p><strong>工程经验</strong>：SOF的检测是CAN控制器硬件自动完成的，软件无需干预。但在总线负载率极高时，SOF可能被噪声淹没导致帧丢失，因此高负载率下应关注总线信号质量。</p></blockquote><p><strong>仲裁场（Arbitration Field）</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>标准帧</th><th>扩展帧</th><th>说明</th></tr></thead><tbody><tr><td>Base ID</td><td>11位</td><td>11位</td><td>基础标识符，高位先发</td></tr><tr><td>SRR</td><td>无</td><td>1位（隐性）</td><td>替代远程请求位，保持与标准帧兼容</td></tr><tr><td>IDE</td><td>1位（显性）</td><td>1位（隐性）</td><td>标识符扩展位，区分标准/扩展帧</td></tr><tr><td>Extended ID</td><td>无</td><td>18位</td><td>扩展标识符</td></tr><tr><td>RTR</td><td>1位</td><td>1位</td><td>远程传输请求位：显性=数据帧，隐性=远程帧</td></tr></tbody></table><p>仲裁场的核心作用是<strong>总线访问优先级判定</strong>。标识符值越小，优先级越高（因为显性位0覆盖隐性位1）。</p><blockquote><p><strong>工程经验</strong>：在电机控制系统中，通常将紧急停止指令分配最低ID（如0x01），周期性状态反馈分配较高ID（如0x100+轴号）。切勿将所有报文设为相同优先级，否则仲裁退化为随机竞争。</p></blockquote><p><strong>控制场（Control Field）</strong> — 6位</p><table tabindex="0"><thead><tr><th>位</th><th>含义</th></tr></thead><tbody><tr><td>IDE（标准帧中）</td><td>已在仲裁场中，此处为保留位r1</td></tr><tr><td>r0</td><td>保留位，显性</td></tr><tr><td>DLC[3:0]</td><td>数据长度码，0~8（标准帧和扩展帧均只支持0~8字节）</td></tr></tbody></table><p>DLC编码表：</p><table tabindex="0"><thead><tr><th>DLC[3:0]</th><th>数据字节数</th></tr></thead><tbody><tr><td>0000</td><td>0</td></tr><tr><td>0001</td><td>1</td></tr><tr><td>...</td><td>...</td></tr><tr><td>1000</td><td>8</td></tr><tr><td>1001~1111</td><td>保留（CAN FD中使用）</td></tr></tbody></table><blockquote><p><strong>工程经验</strong>：DLC=0的数据帧是合法的，常用于心跳信号或同步触发。在电机控制中，建议利用DLC=0帧作为同步信号，减少总线负载。</p></blockquote><p><strong>数据场（Data Field）</strong> — 0~8字节</p><p>数据场承载应用层有效载荷。在电机控制中，典型的数据映射方式：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>字节0-1: 电流/转矩设定值（int16, Q15格式）</span></span>
<span class="line"><span>字节2-3: 速度设定值（int16, RPM或Q15）</span></span>
<span class="line"><span>字节4-5: 位置设定值（int16或int32高16位）</span></span>
<span class="line"><span>字节6-7: 控制字/状态字</span></span></code></pre></div><blockquote><p><strong>工程经验</strong>：8字节限制是CAN 2.0的硬约束。对于需要传输32位位置值+16位速度值+16位电流值+16位状态字的场景（共10字节），需要拆帧或使用CAN FD。拆帧时务必在应用层实现帧序号和完整性校验。</p></blockquote><p><strong>CRC场（Cyclic Redundancy Check）</strong> — 16位</p><p>CRC序列15位 + CRC界定符1位（隐性）。CAN使用的CRC多项式为：</p><ul><li>CRC-15: <span class="katex"><span class="katex-mathml"><math><semantics><mrow><msup><mi>x</mi><mrow><mn>1</mn><mn>5</mn></mrow></msup><mo>+</mo><msup><mi>x</mi><mrow><mn>1</mn><mn>4</mn></mrow></msup><mo>+</mo><msup><mi>x</mi><mrow><mn>1</mn><mn>0</mn></mrow></msup><mo>+</mo><msup><mi>x</mi><mn>8</mn></msup><mo>+</mo><msup><mi>x</mi><mn>7</mn></msup><mo>+</mo><msup><mi>x</mi><mn>4</mn></msup><mo>+</mo><msup><mi>x</mi><mn>3</mn></msup><mo>+</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">x^{15} + x^{14} + x^{10} + x^8 + x^7 + x^4 + x^3 + 1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:0.897438em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit">x</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">5</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathit">x</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">4</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathit">x</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathit">x</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">8</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathit">x</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">7</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathit">x</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">4</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathit">x</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">3</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord mathrm">1</span></span></span></span></li></ul><p>CRC的计算范围包括SOF到数据场的所有位（不含填充位后的结果）。</p><blockquote><p><strong>工程经验</strong>：CRC是CAN通信可靠性的核心保障。在电磁干扰严重的电机驱动环境中，CRC能有效检测位翻转错误。但CRC仅检错不纠错，检测到错误后通过错误帧请求重发。</p></blockquote><p><strong>ACK场</strong> — 2位</p><p>ACK槽（ACK Slot）1位 + ACK界定符1位。发送节点在ACK槽发送隐性位，所有正确接收的节点在ACK槽发送显性位覆盖。ACK界定符固定为隐性位。</p><blockquote><p><strong>工程经验</strong>：如果发送节点在ACK槽读回隐性位，说明没有任何节点正确接收该帧，将触发ACK错误。在单节点调试时（总线上只有一个节点），必然产生ACK错误，这是正常现象——需要接入至少一个其他节点或开启回环模式。</p></blockquote><p><strong>EOF（End of Frame）</strong> — 7位隐性位</p><p>标志帧结束。连续7位隐性位是帧结束的唯一判定条件。</p><p><strong>IFS（Inter Frame Space）</strong> — 3位隐性位</p><p>帧间间隔，用于将当前帧与下一帧分隔开。只有在IFS之后，总线才被认为进入空闲状态。</p><h4 id="_1-3-远程帧" tabindex="-1">1.3 远程帧 <a class="header-anchor" href="#_1-3-远程帧" aria-label="Permalink to &quot;1.3 远程帧&quot;">​</a></h4><p>远程帧（Remote Frame）用于请求某节点发送数据。其结构与数据帧类似，但：</p><ul><li>RTR位为隐性</li><li>无数据场</li><li>DLC表示请求的数据长度</li></ul><blockquote><p><strong>工程经验</strong>：远程帧在实际工程中<strong>极少使用</strong>。原因是：远程帧请求→数据帧响应的过程增加了总线延迟和不确定性。在电机控制中，推荐使用&quot;定时发送&quot;模式替代&quot;请求-响应&quot;模式，确保数据传输的确定性。CiA 301（CANopen）标准也明确不推荐使用远程帧。</p></blockquote><h3 id="_2-仲裁机制" tabindex="-1">2. 仲裁机制 <a class="header-anchor" href="#_2-仲裁机制" aria-label="Permalink to &quot;2. 仲裁机制&quot;">​</a></h3><h4 id="_2-1-线与特性-wired-and" tabindex="-1">2.1 线与特性（Wired-AND） <a class="header-anchor" href="#_2-1-线与特性-wired-and" aria-label="Permalink to &quot;2.1 线与特性（Wired-AND）&quot;">​</a></h4><p>CAN总线物理层的核心特性是<strong>线与（Wired-AND）逻辑</strong>：</p><ul><li><strong>显性位（Dominant, 逻辑0）</strong>：CAN_H ≈ 3.5V, CAN_L ≈ 1.5V，差分电压约2V</li><li><strong>隐性位（Recessive, 逻辑1）</strong>：CAN_H ≈ 2.5V, CAN_L ≈ 2.5V，差分电压约0V</li></ul><p>当多个节点同时发送不同电平时，显性位总是覆盖隐性位——这就是&quot;线与&quot;特性。物理层收发器内部通过开集电极/开漏极结构实现：显性位时驱动管导通拉低总线，隐性位时驱动管关断由终端电阻上拉。</p><h4 id="_2-2-非破坏性仲裁-non-destructive-arbitration" tabindex="-1">2.2 非破坏性仲裁（Non-Destructive Arbitration） <a class="header-anchor" href="#_2-2-非破坏性仲裁-non-destructive-arbitration" aria-label="Permalink to &quot;2.2 非破坏性仲裁（Non-Destructive Arbitration）&quot;">​</a></h4><p>当多个节点同时开始发送时，仲裁过程如下：</p>`,40)),a(t,{code:"sequenceDiagram%0A%20%20%20%20participant%20A%20as%20%E8%8A%82%E7%82%B9A%20(ID%3D0x100)%0A%20%20%20%20participant%20Bus%20as%20%E6%80%BB%E7%BA%BF%0A%20%20%20%20participant%20B%20as%20%E8%8A%82%E7%82%B9B%20(ID%3D0x101)%0A%20%20%20%20A-%3E%3EBus%3A%20SOF%0A%20%20%20%20B-%3E%3EBus%3A%20SOF%0A%20%20%20%20Note%20over%20A%2CB%3A%20%E4%B8%A4%E8%8A%82%E7%82%B9%E5%90%8C%E6%97%B6%E5%BC%80%E5%A7%8B%E5%8F%91%E9%80%81%0A%20%20%20%20A-%3E%3EBus%3A%20ID%E4%BD%8D%200%200%200%201%200%200%200%200%200%200%200%0A%20%20%20%20B-%3E%3EBus%3A%20ID%E4%BD%8D%200%200%200%201%200%200%200%200%200%200%201%0A%20%20%20%20Note%20over%20Bus%3A%20ID0%E4%BD%8D%3A%20A%E5%8F%910(%E6%98%BE%E6%80%A7)%2C%20B%E5%8F%911(%E9%9A%90%E6%80%A7)%3Cbr%2F%3E%E6%80%BB%E7%BA%BF%E4%B8%BA0%2C%20B%E6%A3%80%E6%B5%8B%E5%88%B0%E4%B8%8D%E5%8C%B9%E9%85%8D%0A%20%20%20%20B--xBus%3A%20%E4%BB%B2%E8%A3%81%E5%A4%B1%E8%B4%A5%EF%BC%8C%E8%87%AA%E5%8A%A8%E9%80%80%E5%87%BA%0A%20%20%20%20A-%3E%3EBus%3A%20%E7%BB%A7%E7%BB%AD%E5%8F%91%E9%80%81%E5%AE%8C%E6%95%B4%E5%B8%A7%20%E2%9C%85%20%E4%BB%B2%E8%A3%81%E8%83%9C%E5%87%BA%0A%20%20%20%20Note%20over%20B%3A%20%E8%BD%AC%E4%B8%BA%E6%8E%A5%E6%94%B6%E6%A8%A1%E5%BC%8F%EF%BC%8C%E7%AD%89%E5%BE%85%E6%80%BB%E7%BA%BF%E7%A9%BA%E9%97%B2%E5%90%8E%E9%87%8D%E8%AF%95%0A"}),s[2]||(s[2]=n('<p>仲裁过程的关键特性：</p><ol><li><strong>非破坏性</strong>：胜出节点的报文完整发送，不会被破坏</li><li><strong>逐位仲裁</strong>：每发送一位，节点同时回读总线电平，若不匹配则退出</li><li><strong>优先级确定</strong>：ID值越小，优先级越高（因为高位先发，0覆盖1）</li></ol><h4 id="_2-3-仲裁的工程考量" tabindex="-1">2.3 仲裁的工程考量 <a class="header-anchor" href="#_2-3-仲裁的工程考量" aria-label="Permalink to &quot;2.3 仲裁的工程考量&quot;">​</a></h4><p><strong>优先级倒置问题</strong>：在扩展帧和标准帧混合使用时，由于扩展帧的SRR位为隐性，而标准帧对应位置为RTR（数据帧时为显性），标准帧总是优先于扩展帧——即使扩展帧的Base ID更小。</p>',4)),a(t,{code:"sequenceDiagram%0A%20%20%20%20participant%20Std%20as%20%E6%A0%87%E5%87%86%E5%B8%A7%20ID%3D0x7FF%0A%20%20%20%20participant%20Bus%20as%20%E6%80%BB%E7%BA%BF%0A%20%20%20%20participant%20Ext%20as%20%E6%89%A9%E5%B1%95%E5%B8%A7%20ID%3D0x000%0A%20%20%20%20Std-%3E%3EBus%3A%20SOF%20%2B%20ID%E4%BD%8D%201%201%201%201%201%201%201%201%201%201%201%0A%20%20%20%20Ext-%3E%3EBus%3A%20SOF%20%2B%20ID%E4%BD%8D%200%200%200%200%200%200%200%200%200%200%200%0A%20%20%20%20Note%20over%20Bus%3A%20%E5%89%8D11%E4%BD%8DID%E6%AF%94%E8%BE%83%E5%AE%8C%E6%AF%95%0A%20%20%20%20Std-%3E%3EBus%3A%20RTR%3D0(%E6%98%BE%E6%80%A7)%0A%20%20%20%20Ext-%3E%3EBus%3A%20SRR%3D1(%E9%9A%90%E6%80%A7)%0A%20%20%20%20Note%20over%20Bus%3A%20%E6%A0%87%E5%87%86%E5%B8%A7RTR%3D0(%E6%98%BE%E6%80%A7)%E8%A6%86%E7%9B%96%E6%89%A9%E5%B1%95%E5%B8%A7SRR%3D1(%E9%9A%90%E6%80%A7)%3Cbr%2F%3E%E6%A0%87%E5%87%86%E5%B8%A7%E4%BB%B2%E8%A3%81%E8%83%9C%E5%87%BA%EF%BC%81%0A%20%20%20%20Ext--xBus%3A%20%E4%BB%B2%E8%A3%81%E5%A4%B1%E8%B4%A5%0A%20%20%20%20Std-%3E%3EBus%3A%20%E7%BB%A7%E7%BB%AD%E5%8F%91%E9%80%81%E5%AE%8C%E6%95%B4%E5%B8%A7%20%E2%9C%85%0A"}),s[3]||(s[3]=n('<blockquote><p><strong>工程经验</strong>：在电机控制系统中，<strong>强烈建议统一使用标准帧或统一使用扩展帧</strong>，避免混合使用导致的优先级混乱。如果必须混合，需要仔细分析仲裁场第12位（SRR/RTR）的影响。</p></blockquote><p>:::sim-html comm_sim.html</p><h3 id="_3-位填充规则" tabindex="-1">3. 位填充规则 <a class="header-anchor" href="#_3-位填充规则" aria-label="Permalink to &quot;3. 位填充规则&quot;">​</a></h3><h4 id="_3-1-填充机制" tabindex="-1">3.1 填充机制 <a class="header-anchor" href="#_3-1-填充机制" aria-label="Permalink to &quot;3.1 填充机制&quot;">​</a></h4><p>CAN协议规定：在SOF到CRC界定符之间的区域（即<strong>位填充适用区域</strong>），如果连续出现5个相同电平的位，发送节点自动插入一个相反电平的填充位。</p>',5)),a(t,{code:"flowchart%20LR%0A%20%20%20%20Orig%5B%22%E5%8E%9F%E5%A7%8B%E6%95%B0%E6%8D%AE%3A%5Cn1%201%201%201%201%200%200%200%200%200%201%22%5D%20--%3E%20Stuffed%5B%22%E5%A1%AB%E5%85%85%E5%90%8E%3A%5Cn1%201%201%201%201%20%5B0%5D%200%200%200%200%200%20%5B1%5D%201%22%5D%0A%20%20%20%20Stuffed%20---%20Note1%5B%22%E2%86%91%20%E5%A1%AB%E5%85%85%E4%BD%8D%22%5D%20%26%20Note2%5B%22%E2%86%91%20%E5%A1%AB%E5%85%85%E4%BD%8D%22%5D%0A"}),s[4]||(s[4]=n('<p>接收节点执行逆过程：检测到5个连续相同位后，自动丢弃紧随的填充位。</p><h4 id="_3-2-位填充的影响" tabindex="-1">3.2 位填充的影响 <a class="header-anchor" href="#_3-2-位填充的影响" aria-label="Permalink to &quot;3.2 位填充的影响&quot;">​</a></h4><p><strong>对CRC的影响</strong>：CRC计算基于填充前的原始数据，接收端先去填充再计算CRC。</p><p><strong>对帧长度的影响</strong>：位填充使帧长度变为可变的。最坏情况下，数据场全为0或全为1时，每5位插入1位，帧长度增加约20%。</p><p><strong>对实时性的影响</strong>：填充位增加了传输时间，在计算总线负载率时必须考虑。</p><blockquote><p><strong>工程经验</strong>：在计算最坏情况总线负载率时，应按帧长度增加17%~23%估算（考虑填充位开销）。对于安全关键系统，必须按最坏情况计算。一个简化的估算公式：</p></blockquote><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>L</mi><mrow><mi>s</mi><mi>t</mi><mi>u</mi><mi>f</mi><mi>f</mi></mrow></msub><mo>≈</mo><msub><mi>L</mi><mrow><mi>r</mi><mi>a</mi><mi>w</mi></mrow></msub><mo>+</mo><mo>⌊</mo><mfrac><mrow><msub><mi>L</mi><mrow><mi>r</mi><mi>a</mi><mi>w</mi></mrow></msub></mrow><mrow><mn>5</mn></mrow></mfrac><mo>⌋</mo></mrow><annotation encoding="application/x-tex">L_{stuff} \\approx L_{raw} + \\lfloor \\frac{L_{raw}}{5} \\rfloor </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:1.36033em;"></span><span class="strut bottom" style="height:2.04633em;vertical-align:-0.686em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord"><span class="mord mathit">L</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">s</span><span class="mord mathit">t</span><span class="mord mathit">u</span><span class="mord mathit" style="margin-right:0.10764em;">f</span><span class="mord mathit" style="margin-right:0.10764em;">f</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">≈</span><span class="mord"><span class="mord mathit">L</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathit">a</span><span class="mord mathit" style="margin-right:0.02691em;">w</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mopen">⌊</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathrm">5</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord"><span class="mord mathit">L</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathit">a</span><span class="mord mathit" style="margin-right:0.02691em;">w</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mclose">⌋</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>L</mi><mrow><mi>r</mi><mi>a</mi><mi>w</mi></mrow></msub></mrow><annotation encoding="application/x-tex">L_{raw}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.83333em;vertical-align:-0.15em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit">L</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathit">a</span><span class="mord mathit" style="margin-right:0.02691em;">w</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span> 是填充前的位长度。</p><p><strong>位填充与错误检测的协同</strong>：位填充规则本身也是一种错误检测手段。如果接收节点在填充适用区域内检测到6个或更多连续相同电平位，将触发<strong>填充错误（Stuff Error）</strong>。</p><h3 id="_4-错误处理" tabindex="-1">4. 错误处理 <a class="header-anchor" href="#_4-错误处理" aria-label="Permalink to &quot;4. 错误处理&quot;">​</a></h3><p>CAN协议的错误处理机制是其高可靠性的根本保障，这是CAN区别于UART、SPI等简单通信协议的核心优势。</p><h4 id="_4-1-五种错误类型" tabindex="-1">4.1 五种错误类型 <a class="header-anchor" href="#_4-1-五种错误类型" aria-label="Permalink to &quot;4.1 五种错误类型&quot;">​</a></h4><table tabindex="0"><thead><tr><th>错误类型</th><th>检测条件</th><th>检测节点</th></tr></thead><tbody><tr><td><strong>位错误（Bit Error）</strong></td><td>发送节点发出的电平与总线回读的电平不一致（ACK场和仲裁场除外）</td><td>发送节点</td></tr><tr><td><strong>填充错误（Stuff Error）</strong></td><td>在填充适用区域内检测到6个或更多连续相同电平位</td><td>所有节点</td></tr><tr><td><strong>CRC错误（CRC Error）</strong></td><td>接收节点计算的CRC与接收到的CRC不一致</td><td>接收节点</td></tr><tr><td><strong>格式错误（Form Error）</strong></td><td>固定格式的字段（CRC界定符、ACK界定符、EOF、IFS）出现非法值</td><td>所有节点</td></tr><tr><td><strong>ACK错误（ACK Error）</strong></td><td>发送节点在ACK槽未检测到显性位</td><td>发送节点</td></tr></tbody></table><h4 id="_4-2-错误帧结构" tabindex="-1">4.2 错误帧结构 <a class="header-anchor" href="#_4-2-错误帧结构" aria-label="Permalink to &quot;4.2 错误帧结构&quot;">​</a></h4><p>检测到错误的节点立即发送<strong>错误帧（Error Frame）</strong>，中断当前传输：</p>',15)),a(t,{code:"flowchart%20LR%0A%20%20%20%20subgraph%20%E4%B8%BB%E5%8A%A8%E9%94%99%E8%AF%AF%E5%B8%A7%5B%22%E4%B8%BB%E5%8A%A8%E9%94%99%E8%AF%AF%E5%B8%A7%EF%BC%88Active%20Error%20Frame%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20AF1%5B%22%E9%94%99%E8%AF%AF%E6%A0%87%E5%BF%97%EF%BC%886%E4%BD%8D%E6%98%BE%E6%80%A7%EF%BC%89%5Cn6%E4%B8%AA%E8%BF%9E%E7%BB%AD%E6%98%BE%E6%80%A7%E4%BD%8D%5Cn%E7%A0%B4%E5%9D%8F%E4%BD%8D%E5%A1%AB%E5%85%85%E8%A7%84%E5%88%99%5Cn%E5%BC%95%E8%B5%B7%E6%89%80%E6%9C%89%E8%8A%82%E7%82%B9%E6%A3%80%E6%B5%8B%E5%88%B0%E5%A1%AB%E5%85%85%E9%94%99%E8%AF%AF%5Cn%E5%B9%B6%E8%BF%9E%E9%94%81%E5%8F%91%E9%80%81%E9%94%99%E8%AF%AF%E5%B8%A7%22%5D%20--%3E%20AF2%5B%22%E9%94%99%E8%AF%AF%E7%95%8C%E5%AE%9A%E7%AC%A6%EF%BC%888%E4%BD%8D%E9%9A%90%E6%80%A7%EF%BC%89%5Cn1%E4%BD%8D%E9%9A%90%E6%80%A7%20%2B%207%E4%BD%8D%E9%9A%90%E6%80%A7%5Cn%E7%AD%89%E5%BE%85%E6%80%BB%E7%BA%BF%E6%81%A2%E5%A4%8D%E7%A9%BA%E9%97%B2%22%5D%0A%20%20%20%20end%0A"}),a(t,{code:"flowchart%20LR%0A%20%20%20%20subgraph%20%E8%A2%AB%E5%8A%A8%E9%94%99%E8%AF%AF%E5%B8%A7%5B%22%E8%A2%AB%E5%8A%A8%E9%94%99%E8%AF%AF%E5%B8%A7%EF%BC%88Error%20Passive%20Frame%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20PF1%5B%22%E9%94%99%E8%AF%AF%E6%A0%87%E5%BF%97%EF%BC%886%E4%BD%8D%E9%9A%90%E6%80%A7%EF%BC%89%5Cn6%E4%B8%AA%E8%BF%9E%E7%BB%AD%E9%9A%90%E6%80%A7%E4%BD%8D%5Cn%E4%B8%8D%E5%BD%B1%E5%93%8D%E5%85%B6%E4%BB%96%E8%8A%82%E7%82%B9%E4%BC%A0%E8%BE%93%22%5D%20--%3E%20PF2%5B%22%E9%94%99%E8%AF%AF%E7%95%8C%E5%AE%9A%E7%AC%A6%EF%BC%888%E4%BD%8D%E9%9A%90%E6%80%A7%EF%BC%89%5Cn%E5%90%8C%E4%B8%8A%22%5D%0A%20%20%20%20end%0A"}),s[5]||(s[5]=n('<blockquote><p><strong>工程经验</strong>：主动错误帧的6位显性位会破坏正在传输的帧，这是CAN协议&quot;全局通知错误&quot;的设计哲学——让所有节点都知道当前帧出错。被动错误帧的6位隐性位不会影响总线，这是对&quot;问题节点&quot;的降级处理，防止其持续干扰总线。</p></blockquote><h4 id="_4-3-错误计数器与节点状态" tabindex="-1">4.3 错误计数器与节点状态 <a class="header-anchor" href="#_4-3-错误计数器与节点状态" aria-label="Permalink to &quot;4.3 错误计数器与节点状态&quot;">​</a></h4><p>每个CAN控制器维护两个8位错误计数器：<strong>TEC（发送错误计数器）</strong> 和 <strong>REC（接收错误计数器）</strong>。</p><p>计数规则（简化版）：</p><table tabindex="0"><thead><tr><th>事件</th><th>TEC变化</th><th>REC变化</th></tr></thead><tbody><tr><td>发送节点检测到错误</td><td>+8</td><td>—</td></tr><tr><td>发送节点成功发送</td><td>-1（最小0）</td><td>—</td></tr><tr><td>接收节点检测到错误</td><td>—</td><td>+8</td></tr><tr><td>接收节点成功接收后检测到错误</td><td>—</td><td>+4</td></tr><tr><td>接收节点成功接收</td><td>—</td><td>-1（最小0）</td></tr><tr><td>成功发送后（TEC&gt;127）</td><td>-128（每帧）</td><td>—</td></tr></tbody></table><p>节点状态转换：</p>',6)),a(t,{code:"stateDiagram-v2%0A%20%20%20%20%5B*%5D%20--%3E%20ErrorActive%20%3A%20TEC%E2%89%A4127%20%E4%B8%94%20REC%E2%89%A4127%0A%20%20%20%20ErrorActive%20--%3E%20ErrorPassive%20%3A%20TEC%3E127%20%E6%88%96%20REC%3E127%0A%20%20%20%20ErrorPassive%20--%3E%20ErrorActive%20%3A%20TEC%E2%89%A4127%20%E4%B8%94%20REC%E2%89%A4127%0A%20%20%20%20ErrorPassive%20--%3E%20BusOff%20%3A%20TEC%3E255%0A%20%20%20%20BusOff%20--%3E%20ErrorPassive%20%3A%20%E8%BD%AF%E4%BB%B6%E8%AF%B7%E6%B1%82%E6%81%A2%E5%A4%8D%5Cn%E7%9B%91%E6%8E%A7128%C3%9711%E4%BD%8D%E9%9A%90%E6%80%A7%E4%BD%8D%E5%90%8E%0A%0A%20%20%20%20state%20ErrorActive%20as%20%22Error%20Active%20(%E4%B8%BB%E5%8A%A8%E9%94%99%E8%AF%AF)%22%0A%20%20%20%20state%20ErrorPassive%20as%20%22Error%20Passive%20(%E8%A2%AB%E5%8A%A8%E9%94%99%E8%AF%AF)%22%0A%20%20%20%20state%20BusOff%20as%20%22Bus%20Off%20(%E6%80%BB%E7%BA%BF%E5%85%B3%E9%97%AD)%22%0A"}),s[6]||(s[6]=n('<p><strong>三种状态的行为差异</strong>：</p><table tabindex="0"><thead><tr><th>状态</th><th>错误标志类型</th><th>对总线影响</th><th>发送能力</th></tr></thead><tbody><tr><td>Error Active</td><td>主动错误标志（6位显性）</td><td>中断当前帧</td><td>正常</td></tr><tr><td>Error Passive</td><td>被动错误标志（6位隐性）</td><td>不影响其他节点</td><td>发送前需等待额外空闲时间</td></tr><tr><td>Bus Off</td><td>不发送错误帧</td><td>完全脱离总线</td><td>禁止发送</td></tr></tbody></table><blockquote><p><strong>工程经验</strong>：</p><ol><li><strong>Bus Off恢复策略</strong>：在电机控制中，驱动器进入Bus Off是严重事件。恢复策略通常为：检测到Bus Off后等待一段时间（如100ms），然后请求恢复。恢复后TEC/REC从0开始。频繁Bus Off通常意味着硬件问题（终端电阻缺失、线缆断裂、波特率不匹配）。</li><li><strong>错误计数器监控</strong>：在应用层应定期读取TEC/REC值，当计数器持续增长时，即使未达到Error Passive阈值，也应触发预警——这往往是总线质量恶化的早期信号。</li><li><strong>REC异常增长</strong>：如果某个节点REC持续增长但TEC正常，说明该节点接收能力有问题，可能是晶振偏差过大或采样点配置错误。</li></ol></blockquote><h3 id="_5-总线拓扑与物理层" tabindex="-1">5. 总线拓扑与物理层 <a class="header-anchor" href="#_5-总线拓扑与物理层" aria-label="Permalink to &quot;5. 总线拓扑与物理层&quot;">​</a></h3><h4 id="_5-1-差分信号与抗干扰" tabindex="-1">5.1 差分信号与抗干扰 <a class="header-anchor" href="#_5-1-差分信号与抗干扰" aria-label="Permalink to &quot;5.1 差分信号与抗干扰&quot;">​</a></h4><p>CAN总线采用差分信号传输，这是其强抗干扰能力的物理基础：</p>',6)),a(t,{code:"flowchart%20LR%0A%20%20%20%20subgraph%20%E6%98%BE%E6%80%A7%E4%BD%8D%5B%22%E6%98%BE%E6%80%A7%E4%BD%8D%EF%BC%88%E9%80%BB%E8%BE%910%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20CH_D%5B%22CAN_H%20%E2%89%88%203.5V%22%5D%20--%3E%20Diff_D%5B%22Vdiff%20%E2%89%88%202V%22%5D%0A%20%20%20%20%20%20%20%20CL_D%5B%22CAN_L%20%E2%89%88%201.5V%22%5D%20--%3E%20Diff_D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20%E9%9A%90%E6%80%A7%E4%BD%8D%5B%22%E9%9A%90%E6%80%A7%E4%BD%8D%EF%BC%88%E9%80%BB%E8%BE%911%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20CH_R%5B%22CAN_H%20%E2%89%88%202.5V%20(%E9%9A%90%E6%80%A7%E7%94%B5%E5%B9%B3)%22%5D%20--%3E%20Diff_R%5B%22Vdiff%20%E2%89%88%200V%22%5D%0A%20%20%20%20%20%20%20%20CL_R%5B%22CAN_L%20%E2%89%88%202.5V%20(%E9%9A%90%E6%80%A7%E7%94%B5%E5%B9%B3)%22%5D%20--%3E%20Diff_R%0A%20%20%20%20end%0A"}),s[7]||(s[7]=n('<p>差分信号的优势：</p><ul><li>共模抑制：外部干扰同时作用于CAN_H和CAN_L，差分电压不变</li><li>电磁兼容：差分电流方向相反，辐射相互抵消</li><li>地偏移容忍：节点间地电位差在±2V范围内不影响通信</li></ul><blockquote><p><strong>工程经验</strong>：在电机驱动器中，逆变器开关产生的dv/dt和di/dt噪声是CAN通信的最大威胁。PCB布局时CAN收发器应尽量靠近连接器，CAN_H/CAN_L走线应等长、平行、紧耦合，远离功率走线。必要时使用共模扼流圈（如B82789）抑制共模噪声。</p></blockquote><h4 id="_5-2-终端电阻" tabindex="-1">5.2 终端电阻 <a class="header-anchor" href="#_5-2-终端电阻" aria-label="Permalink to &quot;5.2 终端电阻&quot;">​</a></h4><p>CAN总线两端必须各安装一个<strong>120Ω终端电阻</strong>，作用是：</p><ol><li>阻抗匹配，防止信号反射</li><li>在隐性状态下为总线提供确定的电平</li><li>确保显性/隐性电平的快速切换</li></ol>',6)),a(t,{code:"flowchart%20LR%0A%20%20%20%20Node1%5BNode1%5D%20---%20R1%5B%22120%CE%A9%5Cn(%E7%BB%88%E7%AB%AF)%22%5D%20---%20Bus%5B%22CAN%20Bus%5CnCAN_H%20%2F%20CAN_L%22%5D%20---%20R2%5B%22120%CE%A9%5Cn(%E7%BB%88%E7%AB%AF)%22%5D%20---%20NodeN%5BNodeN%5D%0A%20%20%20%20NodeM%5B%22%E4%B8%AD%E9%97%B4%E8%8A%82%E7%82%B9%5Cn(%E6%97%A0%E7%BB%88%E7%AB%AF%E7%94%B5%E9%98%BB)%22%5D%20---%20Bus%0A"}),s[8]||(s[8]=n('<p>终端电阻的验证方法：断开总线电源，用万用表测量CAN_H和CAN_L之间的直流电阻：</p><ul><li>两个120Ω并联 = <strong>60Ω</strong>（正常）</li><li>120Ω = 只有一端接了终端电阻（异常）</li><li>无穷大 = 两端都没接终端电阻（严重异常）</li></ul><blockquote><p><strong>工程经验</strong>：</p><ol><li>终端电阻的精度影响信号质量，建议使用1%精度的金属膜电阻。</li><li>在实际调试中，&quot;CAN通信不稳定&quot;的根因有50%以上是终端电阻问题——要么缺失，要么多接（中间节点也接了终端电阻）。</li><li>有些收发器（如TJA1050）内部没有终端电阻，必须外接；有些评估板内置了120Ω电阻，使用时需确认是否需要拆除。</li></ol></blockquote><h4 id="_5-3-最大节点数" tabindex="-1">5.3 最大节点数 <a class="header-anchor" href="#_5-3-最大节点数" aria-label="Permalink to &quot;5.3 最大节点数&quot;">​</a></h4><p>CAN协议理论上不限制节点数，但实际受限于：</p><ul><li>收发器驱动能力：通常一个收发器可驱动32~110个节点</li><li>总线电容负载：每个节点增加约10~30pF输入电容</li><li>实际工程中建议<strong>单网段不超过30个节点</strong></li></ul><blockquote><p><strong>工程经验</strong>：电机驱动系统中，通常一个CAN网段连接1~8个驱动器+1个主站。节点数超过30时，应使用CAN中继器或网关分割网段。</p></blockquote><h4 id="_5-4-线缆长度与波特率关系" tabindex="-1">5.4 线缆长度与波特率关系 <a class="header-anchor" href="#_5-4-线缆长度与波特率关系" aria-label="Permalink to &quot;5.4 线缆长度与波特率关系&quot;">​</a></h4><p>线缆长度受信号传播延迟限制。CAN总线上信号的往返延迟（从一端到另一端再返回）必须在一个位时间内完成采样：</p><table tabindex="0"><thead><tr><th>波特率</th><th>最大线缆长度（近似值）</th></tr></thead><tbody><tr><td>1 Mbit/s</td><td>25 m</td></tr><tr><td>500 kbit/s</td><td>100 m</td></tr><tr><td>250 kbit/s</td><td>250 m</td></tr><tr><td>125 kbit/s</td><td>500 m</td></tr><tr><td>50 kbit/s</td><td>1000 m</td></tr><tr><td>20 kbit/s</td><td>2500 m</td></tr></tbody></table><p>计算依据：信号在双绞线中的传播速度约5 ns/m（光速的60%~70%），往返延迟约10 ns/m。加上收发器延迟和时钟容差，经验公式为：</p><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>L</mi><mrow><mi>m</mi><mi>a</mi><mi>x</mi></mrow></msub><mo>≈</mo><mfrac><mrow><msub><mi>t</mi><mrow><mi>b</mi><mi>i</mi><mi>t</mi></mrow></msub><mo>−</mo><mn>2</mn><mo>×</mo><msub><mi>t</mi><mrow><mi>p</mi><mi>r</mi><mi>o</mi><mi>p</mi><mi mathvariant="normal">_</mi><mi>o</mi><mi>t</mi><mi>h</mi><mi>e</mi><mi>r</mi></mrow></msub></mrow><mrow><mn>2</mn><mo>×</mo><msub><mi>t</mi><mrow><mi>p</mi><mi>r</mi><mi>o</mi><mi>p</mi><mi mathvariant="normal">_</mi><mi>p</mi><mi>e</mi><mi>r</mi><mi mathvariant="normal">_</mi><mi>m</mi><mi>e</mi><mi>t</mi><mi>e</mi><mi>r</mi></mrow></msub></mrow></mfrac></mrow><annotation encoding="application/x-tex">L_{max} \\approx \\frac{t_{bit} - 2 \\times t_{prop\\_other}}{2 \\times t_{prop\\_per\\_meter}} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:1.40144em;"></span><span class="strut bottom" style="height:2.45444em;vertical-align:-1.053em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord"><span class="mord mathit">L</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">m</span><span class="mord mathit">a</span><span class="mord mathit">x</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">≈</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.6859999999999999em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord"><span class="mord mathit">t</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">p</span><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathit">o</span><span class="mord mathit">p</span><span class="mord mathrm" style="margin-right:0.02778em;">_</span><span class="mord mathit">p</span><span class="mord mathit">e</span><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathrm" style="margin-right:0.02778em;">_</span><span class="mord mathit">m</span><span class="mord mathit">e</span><span class="mord mathit">t</span><span class="mord mathit">e</span><span class="mord mathit" style="margin-right:0.02778em;">r</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.757em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord"><span class="mord mathit">t</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">b</span><span class="mord mathit">i</span><span class="mord mathit">t</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">−</span><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord"><span class="mord mathit">t</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">p</span><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathit">o</span><span class="mord mathit">p</span><span class="mord mathrm" style="margin-right:0.02778em;">_</span><span class="mord mathit">o</span><span class="mord mathit">t</span><span class="mord mathit">h</span><span class="mord mathit">e</span><span class="mord mathit" style="margin-right:0.02778em;">r</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span></span></p><blockquote><p><strong>工程经验</strong>：</p><ol><li>电机控制常用500 kbit/s或1 Mbit/s，对应线缆长度100m和25m。对于多轴伺服系统，1 Mbit/s + 25m通常足够。</li><li>线缆必须使用<strong>特征阻抗120Ω的双绞线</strong>，不要使用普通平行线。推荐使用CAN专用线缆（如AWG 22~24，特性阻抗120Ω±10%）。</li><li>波特率选择需平衡实时性和可靠性。在电机控制中，500 kbit/s是性价比较高的选择——既保证1ms级控制周期，又有足够的线缆长度裕量。</li></ol></blockquote><h4 id="_5-5-采样点配置" tabindex="-1">5.5 采样点配置 <a class="header-anchor" href="#_5-5-采样点配置" aria-label="Permalink to &quot;5.5 采样点配置&quot;">​</a></h4><p>CAN协议定义了每位时间由多个时间量子（Time Quantum, tq）组成，分为四段：</p>',15)),a(t,{code:"flowchart%20LR%0A%20%20%20%20Sync%5B%22%E5%90%8C%E6%AD%A5%E6%AE%B5(Sync)%5Cn1%20tq%22%5D%20--%3E%20Prop%5B%22%E4%BC%A0%E6%92%AD%E6%AE%B5(Prop)%5Cn1~8%20tq%22%5D%20--%3E%20Phase1%5B%22%E7%9B%B8%E4%BD%8D%E6%AE%B51(Phase1)%5Cn1~8%20tq%22%5D%20--%3E%20SP%5B%22%E2%86%90%20%E9%87%87%E6%A0%B7%E7%82%B9%20%E2%86%92%22%5D%20--%3E%20Phase2%5B%22%E7%9B%B8%E4%BD%8D%E6%AE%B52(Phase2)%5Cn1~8%20tq%22%5D%0A"}),s[9]||(s[9]=n('<p>采样点位置 = (1 + Prop + Phase1) / 总tq数 × 100%</p><p>CiA 301标准推荐采样点位置：</p><ul><li>1 Mbit/s: 75%~87.5%</li><li>500 kbit/s: 87.5%</li><li>125~250 kbit/s: 87.5%</li></ul><blockquote><p><strong>工程经验</strong>：<strong>采样点配置不一致是CAN通信失败的常见原因</strong>。两个通信节点即使波特率相同，如果采样点不同，在高负载率下仍会出现CRC错误。在STM32中，通过BTR寄存器配置Prescaler、Seg1、Seg2来设定采样点。务必确保总线上所有节点的采样点配置一致。</p></blockquote><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>知识点</th><th>核心要点</th><th>工程关键</th></tr></thead><tbody><tr><td>帧格式</td><td>标准帧11位ID，扩展帧29位ID，数据场最大8字节</td><td>统一帧格式，避免混用；8字节限制需在应用层处理</td></tr><tr><td>仲裁机制</td><td>线与特性，ID越小优先级越高，非破坏性</td><td>标准帧优先于扩展帧；合理分配ID优先级</td></tr><tr><td>位填充</td><td>5个相同位后插入填充位</td><td>帧长度增加约17%~23%；填充错误是错误检测手段</td></tr><tr><td>错误处理</td><td>5种错误类型，3种节点状态，错误计数器</td><td>监控TEC/REC趋势；Bus Off恢复策略；REC异常增长预警</td></tr><tr><td>物理层</td><td>差分信号，120Ω终端电阻，线缆长度与波特率反比</td><td>终端电阻验证（60Ω）；采样点一致性；专用双绞线</td></tr></tbody></table><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li>Bosch, &quot;CAN Specification 2.0&quot;, 1991</li><li>CiA 301, &quot;CANopen Application Layer and Communication Profile&quot;</li><li>ISO 11898-1:2015, &quot;Road vehicles — Controller area network (CAN) — Part 1: Data link layer and physical signalling&quot;</li><li>ISO 11898-2:2016, &quot;Road vehicles — Controller area network (CAN) — Part 2: High-speed medium access unit&quot;</li><li>Texas Instruments, &quot;Controller Area Network Physical Layer Requirements&quot; (SLLA270)</li><li>NXP, &quot;TJA1050 High-Speed CAN Transceiver Datasheet&quot;</li></ul>',8))])}const u=e(o,[["render",l]]);export{h as __pageData,u as default};
